/** Live issues keep no assignee after their member leaves. Archived issues stay as they are. */
async function unassignLiveIssues(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  let cursor: string | null = null;

  do {
    const page = await issueRepo.listIssues({
      orgId,
      assigneeId: userId,
      limit: 100,
      cursor,
    });

    for (const issue of page.items) {
      if (issue.assigneeId === null) continue;
      await issueRepo.setIssueAssignee(orgId, issue.id, null);
      await emit("issue.unassigned", {
        ...actorEnvelope(actor),
        issueId: issue.id,
        projectId: issue.projectId,
        previousAssigneeId: issue.assigneeId,
      });
    }

    cursor = page.nextCursor;
  } while (cursor !== null);
}

