  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  let cursor: string | null = null;

  do {
    const page = await issueRepo.listIssues({
      orgId,
      assigneeId: userId,
      limit: 100,
      cursor,
    });

